def move_role_links_to_positions(apps, schema_editor):
    """Everything that was keyed on a Role is re-keyed on the POSITIONS whose current holders had that role.

    A role could be held by many people, so each role link expands to one link per position currently held by
    someone with that role. Roles nobody holds produce no rows (nothing was using them). Safe to re-run.
    """
    from datetime import date

    from django.db.models import Q

    Placement = apps.get_model('accounts', 'Placement')
    Position = apps.get_model('accounts', 'Position')
    Role = apps.get_model('accounts', 'Role')
    RoleAssignment = apps.get_model('platform_core', 'RoleAssignment')
    PositionAssignment = apps.get_model('platform_core', 'PositionAssignment')
    FieldPermission = apps.get_model('platform_core', 'FieldPermission')
    FeatureFlagOverride = apps.get_model('platform_core', 'FeatureFlagOverride')
    ListViewDefinition = apps.get_model('platform_core', 'ListViewDefinition')
    FormFieldPlacement = apps.get_model('platform_core', 'FormFieldPlacement')
    WorkflowStep = apps.get_model('platform_core', 'WorkflowStep')
    ReportDefinition = apps.get_model('platform_core', 'ReportDefinition')
    Dashboard = apps.get_model('platform_core', 'Dashboard')

    today = date.today()
    positions_by_role = {}
    seat_by_user = {}
    placements = (
        Placement.objects.filter(effective_from__lte=today, position__is_active=True)
        .filter(Q(effective_to__isnull=True) | Q(effective_to__gte=today))
        .select_related('employee')
    )
    for placement in placements:
        seat_by_user[placement.employee_id] = placement.position_id
        if placement.employee.role_id:
            positions_by_role.setdefault(placement.employee.role_id, [])
            if placement.position_id not in positions_by_role[placement.employee.role_id]:
                positions_by_role[placement.employee.role_id].append(placement.position_id)

    def seats_for(role_id):
        return positions_by_role.get(role_id, [])

    for old in RoleAssignment.objects.all():
        seats = seats_for(old.role_id)
        own = seat_by_user.get(old.user_id)
        position_id = own if own in seats else (seats[0] if seats else None)
        if position_id is None:
            continue
        PositionAssignment.objects.get_or_create(
            user_id=old.user_id, position_id=position_id, scope_type=old.scope_type, effective_from=old.effective_from,
            defaults=dict(
                scope_values=old.scope_values, include_children=old.include_children, legal_entity_id=old.legal_entity_id,
                effective_to=old.effective_to, granted_by_id=old.granted_by_id, reason=old.reason, is_active=old.is_active,
            ),
        )

    for old in FieldPermission.objects.filter(role__isnull=False, position__isnull=True):
        for position_id in seats_for(old.role_id):
            FieldPermission.objects.get_or_create(
                position_id=position_id, entity_id=old.entity_id, field_code=old.field_code,
                defaults=dict(access=old.access, condition=old.condition, effective_from=old.effective_from, effective_to=old.effective_to),
            )

    for old in FeatureFlagOverride.objects.filter(role__isnull=False, position__isnull=True):
        for position_id in seats_for(old.role_id):
            FeatureFlagOverride.objects.get_or_create(
                flag_id=old.flag_id, position_id=position_id, legal_entity_id=old.legal_entity_id, user_id=None,
                defaults=dict(enabled=old.enabled),
            )

    for old in ListViewDefinition.objects.filter(visibility='role', role__isnull=False):
        for position_id in seats_for(old.role_id):
            copy = ListViewDefinition.objects.filter(entity_id=old.entity_id, code=old.code, position_id=position_id).first()
            if copy is None:
                ListViewDefinition.objects.create(
                    entity_id=old.entity_id, code=old.code, name=old.name, columns=old.columns,
                    default_filters=old.default_filters, default_sort=old.default_sort, visibility='position',
                    position_id=position_id, owner_id=old.owner_id, is_default=old.is_default,
                )

    for placement in FormFieldPlacement.objects.all():
        for role in placement.restricted_to_roles.all():
            placement.restricted_to_positions.add(*seats_for(role.pk))

    for step in WorkflowStep.objects.filter(no_approver_fallback_role__isnull=False):
        seats = seats_for(step.no_approver_fallback_role_id)
        if seats:
            step.no_approver_fallback_position_id = seats[0]
            if step.no_approver_action == 'fallback_role':
                step.no_approver_action = 'fallback_position'
            step.save(update_fields=['no_approver_fallback_position', 'no_approver_action'])

    role_names = {role.name: role.pk for role in Role.objects.all()}
    titles_by_position = dict(Position.objects.values_list('pk', 'title'))
    for report in ReportDefinition.objects.filter(visibility='roles'):
        titles = sorted({
            titles_by_position[position_id]
            for name in report.shared_role_names for position_id in seats_for(role_names.get(name))
            if position_id in titles_by_position
        })
        report.shared_position_titles = titles
        report.visibility = 'positions'
        report.save(update_fields=['shared_position_titles', 'visibility'])

    for dashboard in Dashboard.objects.exclude(role_name=''):
        seats = seats_for(role_names.get(dashboard.role_name))
        if seats and seats[0] in titles_by_position:
            dashboard.position_title = titles_by_position[seats[0]]
            dashboard.save(update_fields=['position_title'])


